38	/**
39	 * Support for integrating auditing within the S3A code.
40	 */
41	public final class AuditIntegration {
42	
43	  /**
44	   * Logging.
45	   */
46	  private static final Logger LOG =
47	      LoggerFactory.getLogger(AuditIntegration.class);
48	
49	  private AuditIntegration() {
50	  }
51	
52	  /**
53	   * Create and start an audit manager.
54	   * @param conf configuration
55	   * @param iostatistics IOStatistics source.
56	   * @return audit manager.
57	   */
58	  public static AuditManagerS3A createAndStartAuditManager(
59	      Configuration conf,
60	      IOStatisticsStore iostatistics) {
61	    ActiveAuditManagerS3A auditManager = new ActiveAuditManagerS3A(
62	        requireNonNull(iostatistics));
63	    auditManager.init(conf);
64	    auditManager.start();
65	    LOG.debug("Started Audit Manager {}", auditManager);
66	    return auditManager;
67	  }
68	
69	  /**
70	   * Return a stub audit manager.
71	   * @return an audit manager.
72	   */
73	  public static AuditManagerS3A stubAuditManager() {
74	    return new NoopAuditManagerS3A();
75	  }
76	
77	  /**
78	   * Create and initialize an audit service.
79	   * The service start operation is not called: that is left to
80	   * the caller.
81	   * @param conf configuration to read the key from and to use to init
82	   * the service.
83	   * @param key key containing the classname
84	   * @param options options to initialize with.
85	   * @return instantiated class.
86	   * @throws IOException failure to initialise.
87	   */
88	  public static OperationAuditor createAndInitAuditor(
89	      Configuration conf,
90	      String key,
91	      OperationAuditorOptions options) throws IOException {
92	    final Class<? extends OperationAuditor> auditClassname
93	        = conf.getClass(
94	        key,
95	        LoggingAuditor.class,
96	        OperationAuditor.class);
97	    try {
98	      LOG.debug("Auditor class is {}", auditClassname);
99	      final Constructor<? extends OperationAuditor> constructor
100	          = auditClassname.getConstructor();
101	      final OperationAuditor instance = constructor.newInstance();
102	      instance.init(options);
103	      return instance;
104	    } catch (NoSuchMethodException | InstantiationException
105	        | RuntimeException
106	        | IllegalAccessException | InvocationTargetException e) {
107	      throw new IOException("Failed to instantiate class "
108	          + auditClassname
109	          + " defined in " + key
110	          + ": " + e,
111	          e);
112	    }
113	  }
114	
115	  /**
116	   * Get the span from a handler context.
117	   * @param request request
118	   * @param <T> type of request.
119	   * @return the span callbacks or null
120	   */
121	  public static <T extends HandlerContextAware> AWSAuditEventCallbacks
122	      retrieveAttachedSpan(final T request) {
123	    return request.getHandlerContext(AUDIT_SPAN_HANDLER_CONTEXT);
124	  }
125	
126	  /**
127	   * Attach a span to a handler context.
128	   * @param request request
129	   * @param span span to attach
130	   * @param <T> type of request.
131	   */
132	  public static <T extends HandlerContextAware> void attachSpanToRequest(
133	      final T request, final AWSAuditEventCallbacks span) {
134	    request.addHandlerContext(AUDIT_SPAN_HANDLER_CONTEXT, span);
135	  }
136	
137	}
