44	/**
45	 * Simple No-op audit manager for use before a real
46	 * audit chain is set up, and for testing.
47	 * Audit spans always have a unique ID and the activation/deactivation
48	 * operations on them will update this audit manager's active span.
49	 * It does have the service lifecycle, so do
50	 * create a unique instance whenever used.
51	 */
52	@InterfaceAudience.Private
53	public class NoopAuditManagerS3A extends CompositeService
54	    implements AuditManagerS3A, NoopSpan.SpanActivationCallbacks {
55	
56	  private static final NoopAuditor NOOP_AUDITOR =
57	      NoopAuditor.createAndStartNoopAuditor(new Configuration(), null);
58	
59	  /**
60	   * The inner auditor.
61	   */
62	  private NoopAuditor auditor = NOOP_AUDITOR;
63	
64	  /**
65	   * Thread local span. This defaults to being
66	   * the unbonded span.
67	   */
68	  private final ThreadLocal<AuditSpanS3A> activeSpan =
69	      ThreadLocal.withInitial(this::getUnbondedSpan);
70	
71	  /**
72	   * ID which is returned as a span ID in the audit event
73	   * callbacks.
74	   */
75	  private final String id;
76	
77	  /**
78	   * Constructor.
79	   * Will create and start a new instance of the auditor.
80	   */
81	  public NoopAuditManagerS3A() {
82	    super("NoopAuditManagerS3A");
83	    id = UUID.randomUUID().toString();
84	  }
85	
86	  @Override
87	  protected void serviceInit(final Configuration conf) throws Exception {
88	    super.serviceInit(conf);
89	    NoopAuditor audit = new NoopAuditor(this);
90	    final OperationAuditorOptions options =
91	        OperationAuditorOptions.builder()
92	            .withConfiguration(conf)
93	            .withIoStatisticsStore(iostatisticsStore().build());
94	    addService(audit);
95	    audit.init(options);
96	  }
97	
98	  @Override
99	  public String getSpanId() {
100	    return id;
101	  }
102	
103	  @Override
104	  public String getOperationName() {
105	    return getName();
106	  }
107	
108	  @Override
109	  public OperationAuditor getAuditor() {
110	    return auditor;
111	  }
112	
113	  /**
114	   * Unbonded span to use after deactivation.
115	   */
116	  private AuditSpanS3A getUnbondedSpan() {
117	    return auditor.getUnbondedSpan();
118	  }
119	
120	  @Override
121	  public AuditSpanS3A getActiveAuditSpan() {
122	    return NoopSpan.INSTANCE;
123	  }
124	
125	  @Override
126	  public AuditSpanS3A createSpan(final String operation,
127	      @Nullable final String path1,
128	      @Nullable final String path2) throws IOException {
129	    return createNewSpan(operation, path1, path2);
130	  }
131	
132	  @Override
133	  public List<RequestHandler2> createRequestHandlers() throws IOException {
134	    return new ArrayList<>();
135	  }
136	
137	  @Override
138	  public TransferStateChangeListener createStateChangeListener() {
139	    return new TransferStateChangeListener() {
140	      public void transferStateChanged(final Transfer transfer,
141	          final Transfer.TransferState state) {
142	      }
143	    };
144	  }
145	
146	  /**
147	   * Forward to the auditor.
148	   * @param path path to check
149	   * @param status status of the path.
150	   * @param mode access mode.
151	   * @throws IOException failure
152	   */
153	  @Override
154	  public boolean checkAccess(final Path path,
155	      final S3AFileStatus status,
156	      final FsAction mode)
157	      throws IOException {
158	    return auditor.checkAccess(path, status, mode);
159	  }
160	
161	  @Override
162	  public void activate(final AuditSpanS3A span) {
163	    activeSpan.set(span);
164	  }
165	
166	  @Override
167	  public void deactivate(final AuditSpanS3A span) {
168	    activate(getUnbondedSpan());
169	  }
170	
171	  /**
172	   * A static source of no-op spans, using the same span ID
173	   * source as managed spans.
174	   * @param name operation name.
175	   * @param path1 first path of operation
176	   * @param path2 second path of operation
177	   * @return a span for the audit
178	   */
179	  public static AuditSpanS3A createNewSpan(
180	      final String name,
181	      final String path1,
182	      final String path2) {
183	    return NOOP_AUDITOR.createSpan(name, path1, path2);
184	  }
185	}
